on conflict(view_key) do nothing;

-- Keep the curriculum exactly at 68 published lessons. Old V29/V30 lesson rows are archived by status rather than hard-deleted.
update public.learning_lessons set content='{"videoUrl":"","article":"База урока — не отдельный сигнал, а набор принципов, по которым принимается решение. В исходном описании акцент стоит на базовых принципах торговли и на переходе от случайных входов к понятной логике.","examples":"Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.","practice":"После просмотра выпиши 3 принципа урока своими словами. Для каждого придумай, как он будет проверяться перед реальной сделкой.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Первый эфир — базовые принципы торговли»?","options":[{"value":"A","label":"Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Первый эфир — базовые принципы торговли» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","facts":["Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","Сигнал без объяснимого принципа не превращается в устойчивую систему.","Базовые правила должны быть одинаковыми от сделки к сделке."],"sourceTitle":"Первый эфир — базовые принципы торговли","sourceDuration":"50 минут 7 секунд","lessonFormat":"video","sourceOrder":1,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='basics-first-live';
update public.learning_lessons set content='{"videoUrl":"","article":"Японская свеча показывает не только направление движения, но и борьбу покупателей и продавцов за выбранный период. Важна форма свечи и её место на графике: одна свеча сама по себе не должна становиться автоматическим сигналом.","examples":"Третий эфир: японские свечи, чтение свечей, настроение рынка, логика входа и домашнее задание.","practice":"Выбери 5 участков графика. Для каждой ключевой свечи запиши: направление, размер тела, тени, контекст и какое настроение она может показывать.","quiz":[{"id":"q1","type":"single_select","question":"Что важно учитывать при чтении свечи?","options":[{"value":"A","label":"Только цвет свечи","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"B","label":"Форму свечи и её контекст на графике","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Только размер депозита","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Только длительность видео","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["B"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Одна свеча сама по себе не должна автоматически становиться сигналом входа.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что помогает превратить свечной анализ в осмысленное решение?","options":[{"value":"A","label":"Контекст предыдущего движения","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Логика входа до сделки","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Игнорирование места свечи на графике","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Вход только потому, что свеча зелёная","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A","B"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Смотри на свечу в контексте предыдущего движения.","facts":["Смотри на свечу в контексте предыдущего движения.","Форма свечи помогает оценить настроение рынка, но не заменяет подтверждение.","Логику входа нужно объяснять до открытия сделки."],"sourceTitle":"Свечи, которые дают деньги","sourceDuration":"42 минуты 37 секунд","lessonFormat":"video","sourceOrder":2,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='candles-third-live';
update public.learning_lessons set content='{"videoUrl":"","article":"Горизонтальный уровень — это область цены, где рынок уже реагировал. Задача анализа не в том, чтобы провести красивую линию, а в том, чтобы найти повторяющуюся реакцию и проверить её контекстом.","examples":"Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.","practice":"Найди 3 уровня на истории. Для каждого отметь минимум две реакции и опиши сценарий входа только после появления подтверждения.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Горизонтальные уровни»?","options":[{"value":"A","label":"Ищи повторные реакции цены, а не одиночное касание.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Горизонтальные уровни» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Ищи повторные реакции цены, а не одиночное касание.","facts":["Ищи повторные реакции цены, а не одиночное касание.","Уровень должен иметь смысл в структуре движения.","Перед входом оцени, как цена подошла к уровню и что делает после реакции."],"sourceTitle":"Горизонтальные уровни","sourceDuration":"43 минуты 36 секунд","lessonFormat":"video","sourceOrder":3,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='technical-horizontal-levels';
update public.learning_lessons set content='{"videoUrl":"","article":"Поддержка и сопротивление лучше воспринимать как зоны, а не как математически точные линии. Цена может проколоть край зоны и всё равно сохранить её смысл. Само касание уровня не является достаточной причиной для входа.","examples":"Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.","practice":"На истории отметь 5 зон. Найди по одному примеру, где вход только на касании дал бы слабое решение, и объясни, какого подтверждения не хватало.","quiz":[{"id":"q1","type":"single_select","question":"Как правильно воспринимать горизонтальный уровень?","options":[{"value":"A","label":"Как точную линию до одного пункта","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"B","label":"Как ценовую зону реакции","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Как гарантию разворота","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Как обязательную точку входа","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["B"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Само касание зоны достаточно для входа.","options":[{"value":"true","label":"Верно","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"false","label":"Неверно","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["false"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что нужно оценить перед входом от зоны?","options":[{"value":"A","label":"Контекст движения","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Реакцию цены","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Только факт касания","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Подтверждение сценария","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Зона имеет ширину и допускает шум цены.","facts":["Зона имеет ширину и допускает шум цены.","Касание зоны ≠ готовый сигнал.","Нужен контекст и подтверждение реакции цены."],"sourceTitle":"Уровни — это зоны, а не линии","sourceDuration":"1 минута 31 секунда","lessonFormat":"video","sourceOrder":4,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='technical-levels-zones';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Order Block» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный инструмент технического анализа: Order Block.","practice":"После изучения «Order Block» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Order Block»?","options":[{"value":"A","label":"Основная тема материала — Order Block.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Order Block» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Основная тема материала — Order Block.","facts":["Основная тема материала — Order Block.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Block","sourceDuration":"10 минут 28 секунд","lessonFormat":"video","sourceOrder":5,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='tools-order-block';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Order Flow» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный материал по Order Flow и чтению потока сделок.","practice":"После изучения «Order Flow» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Order Flow»?","options":[{"value":"A","label":"Основная тема материала — Order Flow.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Order Flow» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Основная тема материала — Order Flow.","facts":["Основная тема материала — Order Flow.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Flow","sourceDuration":"9 минут 49 секунд","lessonFormat":"video","sourceOrder":6,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='tools-order-flow';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Fair Value Gap» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал по Fair Value Gap как отдельному инструменту чтения движения цены.","practice":"После изучения «Fair Value Gap» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Fair Value Gap»?","options":[{"value":"A","label":"Основная тема материала — Fair Value Gap.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Fair Value Gap» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Основная тема материала — Fair Value Gap.","facts":["Основная тема материала — Fair Value Gap.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Fair Value Gap","sourceDuration":"13 минут 18 секунд","lessonFormat":"video","sourceOrder":7,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='tools-fair-value-gap';
update public.learning_lessons set content='{"videoUrl":"","article":"Индикатор — это инструмент чтения уже сформированного движения, а не самостоятельная кнопка BUY/SELL. В уроке собраны MACD, Stochastic, Awesome Oscillator, RSI и Momentum; смысл изучения — понимать, какую информацию даёт каждый инструмент и не перегружать решение.","examples":"Четвёртый эфир: MACD, Stochastic, Awesome Oscillator, RSI и Momentum.","practice":"Для каждого из пяти индикаторов запиши одну функцию: что именно ты хочешь узнать с его помощью. Затем сравни два одинаковых участка графика.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Индикаторы для уверенной торговли»?","options":[{"value":"A","label":"Не смешивай несколько индикаторов без понятной роли каждого.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Индикаторы для уверенной торговли» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Не смешивай несколько индикаторов без понятной роли каждого.","facts":["Не смешивай несколько индикаторов без понятной роли каждого.","Сигнал индикатора нужно сопоставлять с графиком и контекстом.","Настройки и таймфрейм меняют характер сигнала."],"sourceTitle":"Индикаторы для уверенной торговли","sourceDuration":"49 минут 37 секунд","lessonFormat":"video","sourceOrder":8,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='indicators-fourth-live';
update public.learning_lessons set content='{"videoUrl":"","article":"DeMarker используется для оценки состояния движения через положение относительно зон 80/20. В исходном материале указаны период 10, таймфрейм 15 секунд и экспирация M3, а также наблюдение за пересечением уровней на нескольких свечах.","examples":"DeMarker: период 10, уровни 80/20, гистограмма, таймфрейм 15 секунд и экспирация M3; в описании указано ждать пересечение 3–5 свечей.","practice":"На истории найди 5 сигналов DeMarker и для каждого отметь: значение относительно 80/20, направление движения, количество свечей подтверждения и результат сценария.","quiz":[{"id":"q1","type":"single_select","question":"Какие уровни указаны для DeMarker?","options":[{"value":"A","label":"80/20","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"90/10","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"70/30","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"50/50","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"В материале указан период DeMarker 10.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что ещё относится к исходному сценарию?","options":[{"value":"A","label":"Таймфрейм 15 секунд","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Экспирация M3","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Игнорирование тренда","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Наблюдение за пересечением нескольких свечей","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Период: 10; ориентиры: 80/20.","facts":["Период: 10; ориентиры: 80/20.","Не реагируй на единичное касание — смотри на развитие сигнала.","Контекст тренда и волатильности остаётся важен даже при наличии индикатора."],"sourceTitle":"DeMarker","sourceDuration":"5 минут 7 секунд","lessonFormat":"video","sourceOrder":9,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='indicators-demarker';
update public.learning_lessons set content='{"videoUrl":"","article":"В уроке Moving Average рассматривается через периоды 2 и 5, таймфрейм 30 секунд и экспирацию M2. Ключевая идея — наблюдать пересечение средних как изменение краткосрочного баланса, а не считать само пересечение гарантией сделки.","examples":"Moving Average: периоды 2 и 5, таймфрейм 30 секунд, экспирация M2 и логика пересечения.","practice":"Отметь 10 пересечений MA(2) и MA(5). Для каждого запиши, что происходило после закрытия сигнальной свечи.","quiz":[{"id":"q1","type":"single_select","question":"Какие периоды Moving Average указаны в уроке?","options":[{"value":"A","label":"2 и 5","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"10 и 20","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"14 и 21","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"50 и 200","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Для сценария указан таймфрейм 30 секунд и экспирация M2.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что означает пересечение средних в учебном контексте?","options":[{"value":"A","label":"Изменение краткосрочной динамики","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Гарантированный результат","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Сигнал, который нужно оценивать после закрытия свечи","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"D","label":"Причину игнорировать цену","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A","C"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Периоды 2 и 5 задают очень быстрые средние.","facts":["Периоды 2 и 5 задают очень быстрые средние.","Пересечение показывает изменение краткосрочной динамики.","Закрытие свечи важно: не принимай решение по незавершённой свече."],"sourceTitle":"Moving Average","sourceDuration":"3 минуты 2 секунды","lessonFormat":"video","sourceOrder":10,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='indicators-moving-average';
update public.learning_lessons set content='{"videoUrl":"","article":"Stochastic в исходном материале задан уровнями 20/80 и параметрами K14, D3, slowing3. Урок отдельно подчёркивает работу после закрытия свечи и учёт тренда.","examples":"Stochastic: уровни 20/80, K14, D3, slowing 3, M5/M1, работа после закрытия свечи и учёт тренда.","practice":"Сделай 10 разборов Stochastic: направление тренда, положение относительно 20/80, сигнал после закрытия свечи и итог сценария.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Stochastic»?","options":[{"value":"A","label":"20/80 — зоны, а не автоматические точки входа.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Stochastic» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"20/80 — зоны, а не автоматические точки входа.","facts":["20/80 — зоны, а не автоматические точки входа.","Параметры K14/D3/slowing3 должны оставаться фиксированными при отработке учебного сценария.","Сигнал оценивается вместе с трендом и закрытием свечи."],"sourceTitle":"Stochastic","sourceDuration":"7 минут 28 секунд","lessonFormat":"video","sourceOrder":11,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='indicators-stochastic';
update public.learning_lessons set content='{"videoUrl":"","article":"Пробой — это не просто выход цены за линию. В уроке акцент сделан на поиске пробоя, отличии настоящего движения от фейк-пробоя и выборе точки входа. Поэтому сначала определяется уровень и контекст, затем оценивается реакция после выхода.","examples":"Как торговать пробои, находить их, избегать главных ошибок, видеть фейк-пробои и выбирать точки входа.","practice":"Найди 10 пробоев на истории: 5 настоящих и 5 ложных. Для каждого письменно укажи, по какому признаку ты их различаешь.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Стратегия торговли по пробоям»?","options":[{"value":"A","label":"Пробой нужно отличать от ложного выхода за уровень.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Стратегия торговли по пробоям» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Пробой нужно отличать от ложного выхода за уровень.","facts":["Пробой нужно отличать от ложного выхода за уровень.","Контекст и качество движения важнее самого факта пересечения.","Точка входа должна иметь объяснимую причину, а не строиться на погоне за движением."],"sourceTitle":"Стратегия торговли по пробоям","sourceDuration":"14 минут 3 секунды","lessonFormat":"video","sourceOrder":12,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-breakouts';
update public.learning_lessons set content='{"videoUrl":"","article":"Связка SuperTrend + Moving Average нужна для согласования направления движения. SuperTrend даёт контекст направления, а средняя помогает видеть краткосрочную динамику. Примеры в источнике показывают применение на коротком таймфрейме.","examples":"Связка SuperTrend + Moving Average на коротком таймфрейме; в примерах указаны AUD/CAD и EUR/GBP, 1 минута и сделки по +$89.","practice":"На 10 участках графика отметь направление SuperTrend и положение цены относительно MA. Отдельно запиши, были ли условия для входа одновременно.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «SuperTrend + Moving Average»?","options":[{"value":"A","label":"Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «SuperTrend + Moving Average» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","facts":["Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","Сначала определяй направление, затем ищи точку входа.","Примеры сделок не превращают сигнал в гарантию результата."],"sourceTitle":"SuperTrend + Moving Average","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":13,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-supertrend-ma';
update public.learning_lessons set content='{"videoUrl":"","article":"Donchian Channel с периодом 22 показывает диапазон экстремумов выбранного числа свечей. В исходном сценарии используется M1 и экспирация 1–2 минуты. Смысл инструмента — видеть границы текущего диапазона и оценивать выход из него.","examples":"Donchian Channel: период 22, M1, экспирация 1–2 минуты.","practice":"Найди 10 выходов цены за границы Donchian(22) и классифицируй их как продолжение или слабый/ложный выход по контексту.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Donchian Channel»?","options":[{"value":"A","label":"Период 22 задаёт окно наблюдения.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Donchian Channel» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Период 22 задаёт окно наблюдения.","facts":["Период 22 задаёт окно наблюдения.","Граница канала отражает недавний максимум/минимум, а не будущее направление.","Выход за границу нужно оценивать вместе с контекстом."],"sourceTitle":"Donchian Channel","sourceDuration":"4 минуты 17 секунд","lessonFormat":"video","sourceOrder":14,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-donchian';
update public.learning_lessons set content='{"videoUrl":"","article":"Стратегия Александра объединяет Bollinger Bands, RSI и Moving Average. В источнике указаны Bollinger period 20, deviation 2 и EMA, а рабочий контекст — M2–M3. Сила схемы в совместном чтении цены, волатильности и импульса.","examples":"Bollinger Bands + RSI + Moving Average; Bollinger period 20, deviation 2, EMA, M2–M3.","practice":"Разбери 5 сетапов: отдельно запиши показания Bollinger, RSI и MA, а затем сформулируй единый вывод без опоры на один индикатор.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Стратегия Александра»?","options":[{"value":"A","label":"Bollinger показывает положение цены внутри динамического диапазона.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Стратегия Александра» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Bollinger показывает положение цены внутри динамического диапазона.","facts":["Bollinger показывает положение цены внутри динамического диапазона.","RSI добавляет информацию о силе движения.","Moving Average помогает не потерять направление контекста."],"sourceTitle":"Стратегия Александра","sourceDuration":"4 минуты 9 секунд","lessonFormat":"video","sourceOrder":15,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-alexander';
update public.learning_lessons set content='{"videoUrl":"","article":"Связка Schaff Trend Cycle + Donchian Channel сочетает оценку трендового импульса с границами диапазона. Один инструмент отвечает за состояние движения, другой — за положение цены относительно экстремумов.","examples":"Связка Schaff Trend Cycle и Donchian Channel для торгового сценария.","practice":"Найди 8 ситуаций согласования и 4 ситуации конфликта сигналов. Для каждой объясни, почему вход был бы оправдан или почему его лучше пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Schaff Trend Cycle + Donchian Channel»?","options":[{"value":"A","label":"Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Schaff Trend Cycle + Donchian Channel» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","facts":["Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","Ищи согласование направления и положения цены.","Если контекст противоречивый, решение должно быть пропущено, а не выдумано."],"sourceTitle":"Schaff Trend Cycle + Donchian Channel","sourceDuration":"6 минут 33 секунды","lessonFormat":"video","sourceOrder":16,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-schaff-donchian';
update public.learning_lessons set content='{"videoUrl":"","article":"Moving Average помогает читать направление/динамику, а Fractals — локальные экстремумы. Их совместное использование полезно, когда экстремум оценивается относительно текущего направления, а не сам по себе.","examples":"Торговый сценарий с Moving Average и Fractals.","practice":"Отметь 10 фракталов и для каждого запиши положение относительно MA и направление ближайшего движения.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Moving Average + Fractals»?","options":[{"value":"A","label":"Фрактал — это локальная структура, а не самостоятельная причина входа.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Moving Average + Fractals» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Фрактал — это локальная структура, а не самостоятельная причина входа.","facts":["Фрактал — это локальная структура, а не самостоятельная причина входа.","MA задаёт контекст направления.","Сначала оцени структуру, затем ищи точку решения."],"sourceTitle":"Moving Average + Fractals","sourceDuration":"5 минут 21 секунда","lessonFormat":"video","sourceOrder":17,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-ma-fractals';
update public.learning_lessons set content='{"videoUrl":"","article":"Сценарий Giant Candle из источника относится к OTC: таймфрейм 5 секунд, большая свеча сравнивается с 3–5 предыдущими, после чего рассматривается противоположный вход с экспирацией 3 секунды. Это специальный сценарий, который нельзя переносить на любой график без проверки условий.","examples":"OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.","practice":"На истории найди 10 кандидатов Giant Candle и проверь каждый по всем условиям. Отдельно отметь случаи, которые внешне похожи, но не подходят.","quiz":[{"id":"q1","type":"single_select","question":"С чем сравнивается большая свеча в сценарии Giant Candle?","options":[{"value":"A","label":"С одной случайной свечой","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"B","label":"С 3–5 предыдущими свечами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"С дневным депозитом","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"С последними 50 свечами","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["B"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"В источнике сценарий описан для OTC и таймфрейма 5 секунд.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Какие параметры прямо указаны в материале?","options":[{"value":"A","label":"Противоположный вход","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Экспирация 3 секунды","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Игнорирование новой ситуации","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Сравнение с 3–5 свечами","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","facts":["Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","Сценарий предусматривает противоположное направление, но только при выполнении условий.","После новой ситуации нельзя механически повторять старый сигнал."],"sourceTitle":"Giant Candle","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":18,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-giant-candle';
update public.learning_lessons set content='{"videoUrl":"","article":"Паттерн 2-of-3 строится на последовательности зелёная–красная–зелёная. В источнике указано: обычные валютные пары, 30 секунд, третья зелёная должна закрыться на уровне/выше максимума первой зелёной, экспирация 2 минуты.","examples":"Обычные валютные пары, 30 секунд, последовательность зелёная–красная–зелёная; третья зелёная закрывается на/выше максимума первой; экспирация 2 минуты.","practice":"Найди 10 последовательностей и отфильтруй их по всем условиям. Не учитывай незакрытые третьи свечи.","quiz":[{"id":"q1","type":"single_select","question":"Какая последовательность является условием 2-of-3?","options":[{"value":"A","label":"Красная–зелёная–красная","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"B","label":"Зелёная–красная–зелёная","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Три зелёные","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Любые три свечи","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["B"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Третья зелёная свеча должна быть полностью закрыта перед оценкой условия.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Какие условия указаны для сценария?","options":[{"value":"A","label":"30 секунд","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Третья зелёная закрывается на/выше максимума первой зелёной","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Экспирация 2 минуты","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"D","label":"Любой таймфрейм","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A","B","C"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Последовательность свечей должна быть полной: зелёная → красная → зелёная.","facts":["Последовательность свечей должна быть полной: зелёная → красная → зелёная.","Ключевое условие — закрытие третьей свечи на/выше максимума первой зелёной.","Решение принимается после полного закрытия свечи."],"sourceTitle":"2-of-3","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":19,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='strategies-two-of-three';
update public.learning_lessons set content='{"videoUrl":"","article":"База психологии в источнике посвящена типичным проблемам новичков и пошаговым действиям, которые помогают не повторять их. Главная задача — замечать собственные реакции до того, как они превращаются в плохое решение.","examples":"Шестой эфир: проблемы новичков, пошаговые инструкции и базовая психология трейдинга.","practice":"Составь личный список из 5 триггеров: что происходит перед импульсивным решением и какое правило ты применишь в ответ.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Психология трейдинга — база»?","options":[{"value":"A","label":"Проблему нужно сначала назвать, затем определить триггер и действие контроля.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Психология трейдинга — база» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Проблему нужно сначала назвать, затем определить триггер и действие контроля.","facts":["Проблему нужно сначала назвать, затем определить триггер и действие контроля.","Результат одной сделки не должен полностью менять план.","Психология работает вместе с системой, а не вместо неё."],"sourceTitle":"Психология трейдинга — база","sourceDuration":"59 минут 45 секунд","lessonFormat":"video","sourceOrder":20,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='psychology-sixth-live';
update public.learning_lessons set content='{"videoUrl":"https://youtu.be/a9y1pxJfDRU","article":"Главный принцип психологии нужно переводить из общей фразы в конкретное торговое поведение. Если принцип нельзя проверить по действиям трейдера, он остаётся абстракцией.","examples":"Отдельный урок по психологии трейдинга. Домашнее задание озвучено в самом видео.","practice":"После просмотра запиши главный принцип урока своими словами и один измеримый способ проверить его выполнение в течение недели.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Психология трейдинга | Урок 1: главный принцип»?","options":[{"value":"A","label":"Фиксируй состояние до сделки, а не только результат после неё.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Психология трейдинга | Урок 1: главный принцип» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Фиксируй состояние до сделки, а не только результат после неё.","facts":["Фиксируй состояние до сделки, а не только результат после неё.","Разделяй качество решения и финансовый исход.","Домашнее задание должно превращаться в наблюдаемое действие."],"sourceTitle":"Психология трейдинга | Урок 1: главный принцип","sourceDuration":"YouTube","lessonFormat":"video","sourceOrder":21,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='psychology-main-principle';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Инвестинг от А до Я» связывает выбор валютных пар, фильтрацию сигналов и личный подход автора. Практическая цель — научиться не брать каждый доступный сигнал, а выбирать контекст, который соответствует плану.","examples":"Как выбрать валютные пары, какие сигналы пропускать, как автор торгует и выходит в плюс, и какие ошибки делают новички.","practice":"Составь список из 3 валютных пар и критериев отбора. Затем придумай 5 сигналов и отметь, какие из них ты сознательно пропустишь и почему.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Инвестинг от А до Я — мой личный соус»?","options":[{"value":"A","label":"Выбор инструмента — часть стратегии.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Инвестинг от А до Я — мой личный соус» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Выбор инструмента — часть стратегии.","facts":["Выбор инструмента — часть стратегии.","Пропуск слабого сигнала является частью процесса, а не упущенной возможностью.","Личный подход нужно превращать в проверяемые правила."],"sourceTitle":"Инвестинг от А до Я — мой личный соус","sourceDuration":"19 минут 1 секунда","lessonFormat":"video","sourceOrder":22,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='practice-investing-a-to-z';
update public.learning_lessons set content='{"videoUrl":"","article":"Время экспирации должно соответствовать характеру движения. Источник отдельно сравнивает импульс и флет и подчёркивает, что 1 минута не является универсальным решением.","examples":"На что смотреть перед входом, как отличается экспирация при импульсе и флете и почему 1 минута не всегда решение.","practice":"Разбери 10 исторических входов и для каждого выбери экспирацию до просмотра результата. Затем сравни выбор с фактическим движением.","quiz":[{"id":"q1","type":"single_select","question":"От чего в первую очередь следует выбирать экспирацию?","options":[{"value":"A","label":"От характера движения","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"От желания получить больше сделок","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Всегда от 1 минуты","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"От результата предыдущей сделки","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"1 минута является универсальной экспирацией для любого движения.","options":[{"value":"true","label":"Верно","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"false","label":"Неверно","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["false"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что важно оценивать перед выбором экспирации?","options":[{"value":"A","label":"Импульс или флет","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Контекст движения","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Только точку входа без времени","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Поведение цены после входа в исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Сначала оцени характер движения, потом выбирай экспирацию.","facts":["Сначала оцени характер движения, потом выбирай экспирацию.","Импульс и флет требуют разного ожидания по времени.","Точный вход не гарантирует результата при неподходящей экспирации."],"sourceTitle":"Как подбирать время экспирации для сделки?","sourceDuration":"7 минут 57 секунд","lessonFormat":"video","sourceOrder":23,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='timing-expiration';
update public.learning_lessons set content='{"videoUrl":"","article":"Торговая интуиция в контексте урока — это не угадывание, а накопленное распознавание повторяющихся ситуаций. Важно отделять опытное ощущение от импульсивного желания войти.","examples":"Автор показывает сделки по интуиции и объясняет подход на примере трёх сделок.","practice":"Перед каждым из 10 учебных входов сначала запиши интуитивное направление, затем перечисли объективные признаки и только после этого оцени сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Чем полезно отличать интуицию от импульсивного входа?","options":[{"value":"A","label":"Интуиция должна опираться на накопленные признаки","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Интуиция означает отсутствие правил","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Нужно входить сразу при любом ощущении","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Результат трёх сделок доказывает систему","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Интуитивный вход полезно проверять объективными признаками.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что нужно фиксировать при тренировке интуиции?","options":[{"value":"A","label":"Первичное ощущение","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Объективные признаки графика","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Только итог P&L","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Причину решения","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Интуиция должна опираться на наблюдаемые признаки рынка.","facts":["Интуиция должна опираться на наблюдаемые признаки рынка.","Проверяй интуитивный вход теми же правилами, что и обычный.","Три удачных сделки не доказывают устойчивость подхода."],"sourceTitle":"Торговля по интуиции","sourceDuration":"11 минут 53 секунды","lessonFormat":"video","sourceOrder":24,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='practice-intuition';
update public.learning_lessons set content='{"videoUrl":"","article":"Разбор недели нужен не для поиска виноватой стратегии, а для выявления повторяющихся причин потерь. Сделку следует оценивать по процессу: контекст, вход, риск, дисциплина и результат.","examples":"Пятый эфир: причины потери средств, разбор сделок и причины различий в результатах трейдеров.","practice":"Возьми последние 10 сделок и раздели ошибки на: анализ, вход, риск, дисциплина. Найди одну повторяющуюся причину и сформулируй правило против неё.","quiz":[{"id":"q1","type":"single_select","question":"Что важнее искать в разборе недели?","options":[{"value":"A","label":"Повторяющиеся причины ошибок","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Одну виноватую сделку","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Только максимальный плюс","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Только название стратегии","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"Убыточная сделка автоматически означает, что система плохая.","options":[{"value":"true","label":"Верно","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"false","label":"Неверно","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["false"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что стоит сравнивать при разборе сделок?","options":[{"value":"A","label":"Контекст","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Качество входа","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Риск и дисциплину","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"D","label":"Только сумму прибыли","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A","B","C"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Одна убыточная сделка не равна плохой системе.","facts":["Одна убыточная сделка не равна плохой системе.","Повторяющаяся ошибка важнее единичного результата.","Сравнивай причины разных результатов, а не только суммы P&L."],"sourceTitle":"Итоги недели — разбор ошибок","sourceDuration":"38 минут 57 секунд","lessonFormat":"video","sourceOrder":25,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='trade-review-week-errors';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Разбор рынка — 15.07.2025» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — 15.07.2025. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри материал и затем найди 3 похожие ситуации на истории. Для каждой запиши: контекст, ключевой признак из урока, ожидаемое направление, условие входа и что отменяет сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Разбор рынка — 15.07.2025»?","options":[{"value":"A","label":"Главная тема урока — Разбор рынка — 15.07.2025.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Разбор рынка — 15.07.2025» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Главная тема урока — Разбор рынка — 15.07.2025.","facts":["Главная тема урока — Разбор рынка — 15.07.2025.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — 15.07.2025","sourceDuration":"7 минут 18 секунд","lessonFormat":"video","sourceOrder":26,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='market-15072025';
