update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Фейк-пробой, импульс и откат» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: фейк-пробой, импульс и откат. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри материал и затем найди 3 похожие ситуации на истории. Для каждой запиши: контекст, ключевой признак из урока, ожидаемое направление, условие входа и что отменяет сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Фейк-пробой, импульс и откат»?","options":[{"value":"A","label":"Главная тема урока — Фейк-пробой, импульс и откат.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Фейк-пробой, импульс и откат» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Главная тема урока — Фейк-пробой, импульс и откат.","facts":["Главная тема урока — Фейк-пробой, импульс и откат.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Фейк-пробой, импульс и откат","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":42,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='market-false-breakout';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Как понять, куда движется рынок?» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: как понять, куда движется рынок?. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри материал и затем найди 3 похожие ситуации на истории. Для каждой запиши: контекст, ключевой признак из урока, ожидаемое направление, условие входа и что отменяет сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Как понять, куда движется рынок?»?","options":[{"value":"A","label":"Главная тема урока — Как понять, куда движется рынок?.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Как понять, куда движется рынок?» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}]