update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Фазы рынка» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: фазы рынка. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри материал и затем найди 3 похожие ситуации на истории. Для каждой запиши: контекст, ключевой признак из урока, ожидаемое направление, условие входа и что отменяет сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Фазы рынка»?","options":[{"value":"A","label":"Главная тема урока — Фазы рынка.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Фазы рынка» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Главная тема урока — Фазы рынка.","facts":["Главная тема урока — Фазы рынка.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Фазы рынка","sourceDuration":"10 минут 20 секунд","lessonFormat":"video","sourceOrder":45,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='market-phases';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Как я анализирую рынок — полный разбор» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: как я анализирую рынок — полный разбор. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри материал и затем найди 3 похожие ситуации на истории. Для каждой запиши: контекст, ключевой признак из урока, ожидаемое направление, условие входа и что отменяет сценарий.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Как я анализирую рынок — полный разбор»?","options":[{"value":"A","label":"Главная тема урока — Как я анализирую рынок — полный разбор.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Как я анализирую рынок — полный разбор» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Главная тема урока — Как я анализирую рынок — полный разбор.","facts":["Главная тема урока — Как я анализирую рынок — полный разбор.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Как я анализирую рынок — полный разбор","sourceDuration":"13 минут 58 секунд","lessonFormat":"video","sourceOrder":46,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='market-analysis-duplicate';
update public.learning_lessons set content='{"videoUrl":"","article":"Материал «Важность долгосрочной прибыли» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Аудио о важности долгосрочного результата и системного взгляда на прибыль.","practice":"Сформулируй по материалу «Важность долгосрочной прибыли» 3 личных правила. Для каждого укажи триггер, действие и способ проверить соблюдение через неделю.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Важность долгосрочной прибыли»?","options":[{"value":"A","label":"Главная тема — Важность долгосрочной прибыли.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Важность долгосрочной прибыли» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","la