update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Концепция работы в Amir Family Exclusive» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал о концепции работы в Amir Family Exclusive и механике авторской модели.","practice":"После изучения «Концепция работы в Amir Family Exclusive» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Концепция работы в Amir Family Exclusive»?","options":[{"value":"A","label":"Основная тема материала — Концепция работы в Amir Family Exclusive.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Концепция работы в Amir Family Exclusive» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Основная тема материала — Концепция работы в Amir Family Exclusive.","facts":["Основная тема материала — Концепция работы в Amir Family Exclusive.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Концепция работы в Amir Family Exclusive","sourceDuration":"9 минут 30 секунд","lessonFormat":"video","sourceOrder":48,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='advanced-amir-family';
update public.learning_lessons set content='{"videoUrl":"","article":"Материал «Как понять, когда не стоит торговать?» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Гайд о ситуациях, когда лучше не торговать, с акцентом на сохранение денег и долгосрочный результат.","practice":"Сформулируй по материалу «Как понять, когда не стоит торговать?» 3 личных правила. Для каждого укажи триггер, действие и способ проверить соблюдение через неделю.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Как понять, когда не стоит торговать?»?","options":[{"value":"A","label":"Главная тема — Как понять, когда не стоит торговать?.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Как понять, когда не стоит торговать?» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относи