update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Книга «Зональный трейдинг»» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Книга о зонах, эмоциях, психологии и практических советах.","practice":"После изучения «Книга «Зональный трейдинг»» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Книга «Зональный трейдинг»»?","options":[{"value":"A","label":"Основная тема материала — Книга «Зональный трейдинг».","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Книга «Зональный трейдинг»» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что отн