update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Forex: кто двигает цену?» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал о том, кто двигает цену, почему рынок активен в определённые периоды и какую роль играют банки.","practice":"После изучения «Forex: кто двигает цену?» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Forex: кто двигает цену?»?","options":[{"value":"A","label":"Основная тема материала — Forex: кто двигает цену?.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Forex: кто двигает цену?» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Основная тема материала — Forex: кто двигает цену?.","facts":["Основная тема материала — Forex: кто двигает цену?.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Forex: кто двигает цену?","sourceDuration":"13 минут 55 секунд","lessonFormat":"video","sourceOrder":56,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='advanced-forex-market';
update public.learning_lessons set content='{"videoUrl":"","article":"Урок «Новое обучение аналитика — личная стратегия» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Новый обучающий материал аналитика о личной торговой стратегии.","practice":"После изучения «Новое обучение аналитика — личная стратегия» выпиши 3 правила своими словами и примени их на 5 исторических примерах. Для каждого примера объясни, какое условие сработало или почему вход нужно было пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Новое обучение аналитика — личная стратегия»?","options":[{"value":"A","label":"Основная тема материала — Новое обучение аналитика — личная стратегия.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Новое обучение аналитика — личная стратегия» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, з