update public.learning_lessons set content='{"videoUrl":"","article":"Запись «Первая эксклюзивная сессия» используй как тренировку наблюдения. Не пытайся просто повторить сделки из записи. Отслеживай, что трейдер видел до решения: структуру, движение цены, уровень, реакцию и причины входа/пропуска.\n\nТвоя цель — поставить запись на паузу перед ключевым моментом и самостоятельно сформулировать сценарий, а затем сравнить его с решением автора.","examples":"Запись торговой сессии: Первая эксклюзивная сессия. Используй запись как практический материал для наблюдения за решениями и контекстом.","practice":"Посмотри «Первая эксклюзивная сессия» с паузами. Перед каждым заметным входом запиши свой сценарий и причину. После решения автора сравни: совпал ли контекст, условие входа и ожидание.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Первая эксклюзивная сессия»?","options":[{"value":"A","label":"Запись сессии — материал для тренировки процесса принятия решений.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Первая эксклюзивная сессия» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Запись сессии — материал для тренировки процесса принятия решений.","facts":["Запись сессии — материал для тренировки процесса принятия решений.","Главное — причина действия до результата, а не сам факт плюса или минуса.","Пауза перед входом превращает просмотр в активную практику."],"sourceTitle":"Первая эксклюзивная сессия","sourceDuration":"27 минут 7 секунд","lessonFormat":"session","sourceOrder":58,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='session-first-exclusive';
