abel":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Тема справочника — Bull / Bear Flag.","facts":["Тема справочника — Bull / Bear Flag.","Паттерн — это структура, которую нужно читать в контексте движения.","Перед входом заранее определи подтверждение и отмену сценария."],"sourceTitle":"Bull / Bear Flag","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":66,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='patterns-flags';
