update public.learning_lessons set content='{"videoUrl":"","article":"Материал «Top 3 индикатора, Top 3 ошибки и самотест трейдера» нужен как справочник структуры на графике. Паттерн нельзя распознавать только по внешнему сходству: сначала найди его границы, контекст и точку подтверждения.\n\nИспользуй название паттерна как гипотезу, а не как готовую сделку. Сценарий считается понятным только тогда, когда ты можешь назвать условие появления, подтверждение и ситуацию, при которой идея перестаёт работать.","examples":"Сборник: RSI, MACD, Keltner Channel; ошибки с объёмом/ликвидностью, излишней уверенностью после серии плюсов и зависимостью от одного таймфрейма/актива; в конце — самотест настоящего трейдера.","practice":"Найди на графике 5 примеров «Top 3 индикатора, Top 3 ошибки и самотест трейдера»: 3 качественных и 2 спорных. Для каждого объясни, почему структура подходит или почему её лучше не считать полноценным сигналом.","quiz":[{"id":"q1","type":"single_select","question":"Что является главным фокусом урока «Top 3 индикатора, Top 3 ошибки и самотест трейдера»?","options":[{"value":"A","label":"Тема справочника — Top 3 индикатора, Top 3 ошибки и самотест трейдера.","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Автоматический заработок без анализа","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"C","label":"Настройка интерфейса дневника","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Игнорирование контекста рынка","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["A"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q2","type":"true_false","question":"При изучении «Top 3 индикатора, Top 3 ошибки и самотест трейдера» важно оценивать решение в контексте, а не только его итог.","options":[{"value":"true","label":"Верно","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"false","label":"Неверно","feedback":"Неверно: этот вариант противоречит материалу."}],"correctValues":["true"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."},{"id":"q3","type":"multi_select","question":"Что относится к правильному изучению материала?","options":[{"value":"A","label":"Сформулировать правило своими словами","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"B","label":"Проверить его на исторических примерах","feedback":"Правильно: этот вариант соответствует материалу."},{"value":"C","label":"Считать любой сигнал гарантией результата","feedback":"Неверно: этот вариант противоречит материалу."},{"value":"D","label":"Уметь назвать условие пропуска","feedback":"Правильно: этот вариант соответствует материалу."}],"correctValues":["A","B","D"],"hint":"Сначала вспомни правило из теории урока, затем сравни его с каждым вариантом."}],"keyTakeaway":"Тема справочника — Top 3 индикатора, Top 3 ошибки и самотест трейдера.","facts":["Тема справочника — Top 3 индикатора, Top 3 ошибки и самотест трейдера.","Паттерн — это структура, которую нужно читать в контексте движения.","Перед входом заранее определи подтверждение и отмену сценария."],"sourceTitle":"Top 3 индикатора, Top 3 ошибки и самотест трейдера","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":68,"curriculumVersion":"V32 ACADEMY"}'::jsonb,status='published',updated_at=now() where slug='patterns-top3-mistakes-selftest';

